+const SIZES = ['xs', 'sm', 'md', 'lg', 'xl'];
+
+function fontSize(count, max) {
+  if (max <= 0) return SIZES[0];
+  const idx = Math.min(SIZES.length - 1, Math.floor((count / max) * SIZES.length));
+  return SIZES[idx];
+}
+
+module.exports = { fontSize, SIZES };
